{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "srs-network://contracts/request.schema.json",
  "title": "Request",
  "description": "Normalized form of a /srs-network invocation; scripts/runtime/controller/core.py::RunController.start validates every request against this schema before creating a run.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "mode",
    "domains",
    "targets",
    "restrictions",
    "publish_requested"
  ],
  "properties": {
    "mode": {
      "type": "string",
      "enum": [
        "draft",
        "review-domain",
        "review-re",
        "improve",
        "prepare-publish",
        "publish",
        "pipeline"
      ]
    },
    "domains": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "enum": [
          "ethernet",
          "someip"
        ]
      },
      "description": "One or more domains, e.g. mode=improve domains=ethernet,someip."
    },
    "targets": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Leaf modes: files and directories may be mixed; directories expand recursively, paths are deduplicated and frozen when the run starts. Draft/pipeline: approved source documents. Directory selection never implies retire.",
      "minItems": 1
    },
    "baseline_ref": {
      "type": [
        "string",
        "null"
      ],
      "description": "입력 기준본: the revision/commit/CodeBeamer snapshot this request is evaluated against. Null means \"working tree as-is\"."
    },
    "restrictions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "제한: explicit scope restrictions the requester stated (e.g. \"검토만, 원문 변경 금지\")."
    },
    "publish_requested": {
      "type": "boolean",
      "description": "True only for mode=publish. A request must not silently escalate to publish."
    },
    "review_reuse_policy": {
      "type": "string",
      "enum": [
        "reuse_valid_pass_stamps",
        "force_full_review"
      ],
      "description": "Review-bearing modes only. Top-level /srs-network selects this policy before dispatch; controller-level mode validation makes it required when replay behavior is enabled."
    },
    "module_scope_judgment": {
      "type": "string",
      "enum": [
        "full_rescan",
        "changed_members_only"
      ],
      "description": "Review-bearing modes only; optional, defaults to full_rescan. Selects what a module/L2-scope rule (e.g. semantic_duplication) re-judges once its group fingerprint moves. full_rescan re-judges every member each round. changed_members_only narrows the re-judgment to members whose content actually moved since the stamped round -- dispatch is unchanged either way, so the reviewer still READS the whole group and only the judged subset shrinks. Falls back to a full rescan whenever the member diff is not trustworthy (no prior stamp, a non-content invalidation reason, or a changed member set)."
    },
    "workspace_root": {
      "type": [
        "string",
        "null"
      ],
      "description": "mode=draft/pipeline only: the module/domain root directory to scan for already-existing uid/display-id values, so scripts/runtime/uid_allocator.py never mints a value that collides with a real leaf outside this batch. 'targets' means something different for mode=draft/pipeline (approved source document paths for steps/prepare-context.md, not leaves to scan) -- this field is what supplies the collision-avoidance root instead. Null/omitted for every other mode. Required (non-null) when mode=draft or mode=pipeline -- enforced by scripts/runtime/controller/core.py, not this schema, because schema_check.py's supported subset has no allOf/nested-if for a second mode-conditional (see its own module docstring)."
    },
    "approved_plan_path": {
      "type": [
        "string",
        "null"
      ],
      "description": "mode=publish only: path to a publish-plan.json a human has already approved (normally a prior mode=prepare-publish run's plan_path artifact, after that run's publish-preview.txt was actually read). scripts/runtime/controller/handlers/publish.py::accept_publish re-fetches a fresh CodeBeamer baseline and only proceeds when regenerating the plan from it still matches this file's plan_fingerprint (planner.py::approval_still_valid) -- this field only names which approval to check against, it is never trusted blindly. Null/omitted for every other mode. Required (non-null) when mode=publish -- enforced by scripts/runtime/controller/core.py, same reason as workspace_root above."
    },
    "retire_missing": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "parent_cb_ids",
        "complete_local_set"
      ],
      "properties": {
        "parent_cb_ids": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "integer",
            "minimum": 1
          }
        },
        "complete_local_set": {
          "const": true,
          "type": "boolean"
        }
      },
      "description": "prepare-publish only. Explicit authorization to compare the complete local leaf set for these parent folders against their remote children and propose missing-item retire operations. Omit to disable retire. A reviewed plan still requires separate publish approval."
    }
  },
  "if": {
    "properties": {
      "mode": {
        "const": "publish"
      }
    }
  },
  "then": {
    "properties": {
      "publish_requested": {
        "const": true
      }
    }
  }
}

